#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum SourceOccupant {
    Reserved,
    ImportedLive,
    Authored(u16),
    PlayerFireball(u32),
    ArcherArrow(u32),
    FireflyFireball(u32),
    CastleBuild(u32),
    CastleRoot(u32),
    CastleConstruction(u32),
    CastleDefense(u32),
    CastleDefenseShot(u32),
    CastleAssociation(u32),
    Possession(u32),
    PossessionImpact(u32),
    GroundFire(u32),
    PossessionAttraction(u32),
    StrongPossessionImpact(u32),
    FireballImpact(u32),
    WaterSplash(u32),
    ManaSphere(u32),
    ManaCarrier(u32),
    DeathBurst(u32),
    PlayerDeathMarker(u16),
    SpeedTrail(u32),
    CheckpointSmoke(u32),
    SpellPickup {
        family: u8,
    },
    Ambient(u16),
    MultipartSegment(u16),
    Resident {
        source_entity_index: u16,
        model: u8,
        action: u8,
    },
}

impl SourceOccupant {
    fn source_spawn_kind(self) -> Result<Level1SourceSpawnKind, String> {
        match self {
            Self::Reserved => Ok(Level1SourceSpawnKind::Reserved),
            Self::ImportedLive => Ok(Level1SourceSpawnKind::ImportedResetTuple),
            // The open authored payload is validated against the canonical
            // 308-record activation manifest by the source-sprite census.
            Self::Authored(_) => Ok(Level1SourceSpawnKind::AuthoredActivationTuple),
            Self::PlayerFireball(_) => Ok(Level1SourceSpawnKind::PlayerFireball),
            Self::ArcherArrow(_) => Ok(Level1SourceSpawnKind::ArcherArrow),
            Self::FireflyFireball(_) => Ok(Level1SourceSpawnKind::FireflyFireball),
            Self::CastleBuild(_) => Ok(Level1SourceSpawnKind::CastleBuild),
            Self::CastleRoot(_) => Ok(Level1SourceSpawnKind::CastleRoot),
            Self::CastleConstruction(_) => Ok(Level1SourceSpawnKind::CastleConstruction),
            Self::CastleDefense(_) => Ok(Level1SourceSpawnKind::CastleDefenseController),
            Self::CastleDefenseShot(_) => Ok(Level1SourceSpawnKind::CastleDefenseShot),
            Self::CastleAssociation(_) => Ok(Level1SourceSpawnKind::CastleAssociation),
            Self::Possession(_) => Ok(Level1SourceSpawnKind::Possession),
            Self::PossessionImpact(_) => Ok(Level1SourceSpawnKind::PossessionImpact),
            Self::GroundFire(_) => Ok(Level1SourceSpawnKind::GroundFire),
            Self::PossessionAttraction(_) => Ok(Level1SourceSpawnKind::PossessionAttraction),
            Self::StrongPossessionImpact(_) => Ok(Level1SourceSpawnKind::StrongPossessionImpact),
            Self::FireballImpact(_) => Ok(Level1SourceSpawnKind::FireballImpact),
            Self::WaterSplash(_) => Ok(Level1SourceSpawnKind::WaterSplash),
            Self::ManaSphere(_) => Ok(Level1SourceSpawnKind::ManaSphere),
            Self::ManaCarrier(_) => Ok(Level1SourceSpawnKind::ManaCarrier),
            Self::DeathBurst(_) => Ok(Level1SourceSpawnKind::DeathBurst),
            Self::PlayerDeathMarker(_) => Ok(Level1SourceSpawnKind::PlayerDeathMarker),
            Self::SpeedTrail(_) => Ok(Level1SourceSpawnKind::SpeedTrail),
            Self::CheckpointSmoke(_) => Ok(Level1SourceSpawnKind::CheckpointSmoke),
            Self::SpellPickup { family } => spell_pickup_spawn_kind(family),
            Self::Ambient(_) => Ok(Level1SourceSpawnKind::Ambient),
            Self::MultipartSegment(_) => Ok(Level1SourceSpawnKind::MultipartSegment),
            Self::Resident { model, action, .. } => resident_spawn_kind(model, action),
        }
    }

    const fn dynamic_shape(self) -> Option<(u8, u8, u8)> {
        match self {
            Self::PlayerFireball(_) | Self::FireflyFireball(_) => {
                Some((FIREBALL_PROJECTILE_CLASS, FIREBALL_PROJECTILE_MODEL, 0))
            }
            Self::ArcherArrow(_) => Some((
                ARCHER_ARROW_PROJECTILE_CLASS,
                ARCHER_ARROW_PROJECTILE_MODEL,
                13,
            )),
            Self::CastleBuild(_) => Some((
                CASTLE_PROJECTILE_CLASS,
                CASTLE_PROJECTILE_MODEL,
                CASTLE_PROJECTILE_ACTION,
            )),
            Self::CastleRoot(_) => Some((CASTLE_ROOT_CLASS, CASTLE_ROOT_MODEL, CASTLE_ROOT_ACTION)),
            Self::CastleConstruction(_) => Some((
                CASTLE_CONSTRUCTION_CLASS,
                CASTLE_CONSTRUCTION_MODEL,
                CASTLE_CONSTRUCTION_ACTION,
            )),
            Self::CastleDefense(_) => Some((
                CASTLE_DEFENSE_CLASS,
                CASTLE_DEFENSE_MODEL,
                CASTLE_DEFENSE_ACTION,
            )),
            // `sub_6DCA0` selects one of five concrete constructors. The
            // caller binds that exact post-rewrite tuple after allocation.
            Self::CastleDefenseShot(_) => None,
            Self::CastleAssociation(_) => Some((
                CASTLE_ASSOCIATION_CLASS,
                CASTLE_ASSOCIATION_MODEL,
                CASTLE_ASSOCIATION_ACTION,
            )),
            Self::Possession(_) => Some((
                POSSESSION_PROJECTILE_CLASS,
                POSSESSION_PROJECTILE_MODEL,
                POSSESSION_PROJECTILE_ACTION,
            )),
            Self::PossessionImpact(_) => Some((
                POSSESSION_IMPACT_CLASS,
                POSSESSION_IMPACT_MODEL,
                POSSESSION_IMPACT_ACTION,
            )),
            Self::GroundFire(_) => {
                Some((FIREBALL_IMPACT_CLASS, GROUND_FIRE_MODEL, GROUND_FIRE_ACTION))
            }
            Self::PossessionAttraction(_) => Some((
                FIREBALL_IMPACT_CLASS,
                POSSESSION_ATTRACTION_MODEL,
                POSSESSION_ATTRACTION_ACTION,
            )),
            Self::StrongPossessionImpact(_) => Some((
                POSSESSION_IMPACT_CLASS,
                POSSESSION_STRONG_IMPACT_MODEL,
                POSSESSION_STRONG_IMPACT_ACTION,
            )),
            Self::FireballImpact(_) => Some((FIREBALL_IMPACT_CLASS, FIREBALL_IMPACT_MODEL, 0)),
            Self::WaterSplash(_) => Some((FIREBALL_IMPACT_CLASS, WATER_SPLASH_MODEL, 5)),
            Self::ManaSphere(_) => Some((MANA_SPHERE_CLASS, MANA_SPHERE_MODEL, MANA_SPHERE_ACTION)),
            Self::ManaCarrier(_) => {
                Some((MANA_CARRIER_CLASS, MANA_CARRIER_MODEL, MANA_CARRIER_ACTION))
            }
            Self::DeathBurst(_) => Some((DEATH_BURST_CLASS, DEATH_BURST_MODEL, DEATH_BURST_ACTION)),
            Self::PlayerDeathMarker(_) => Some((
                PLAYER_DEATH_MARKER_CLASS,
                PLAYER_DEATH_MARKER_MODEL,
                PLAYER_DEATH_MARKER_ACTION,
            )),
            Self::SpeedTrail(_) => Some((SPEED_TRAIL_CLASS, SPEED_TRAIL_MODEL, SPEED_TRAIL_ACTION)),
            Self::CheckpointSmoke(_) => Some((
                CHECKPOINT_SMOKE_CLASS,
                CHECKPOINT_SMOKE_MODEL,
                CHECKPOINT_SMOKE_ACTION,
            )),
            Self::SpellPickup { family } => Some((
                SPELL_PICKUP_CLASS,
                family,
                SPELL_RESPAWNING_PICKUP_ACTIONS[family as usize],
            )),
            Self::Ambient(_) => None,
            Self::MultipartSegment(_) => Some((
                MISSION_ACTOR_CLASS,
                MULTIPART_MODEL,
                MULTIPART_SEGMENT_ACTION,
            )),
            Self::Resident { model, action, .. } => Some((MISSION_ACTOR_CLASS, model, action)),
            Self::Reserved | Self::ImportedLive | Self::Authored(_) => None,
        }
    }

    fn dynamic_shape_matches(self, record: Level1ResetSourceSlot) -> bool {
        let Some((class, model, action)) = self.dynamic_shape() else {
            return true;
        };
        if matches!(self, Self::MultipartSegment(_)) {
            // A multipart segment keeps its typed source-pool occupant while
            // its source row briefly uses action 29 during kill/removal. The
            // row remains map-linked until the source cleanup phase, so this
            // is a known lifecycle transition rather than an unknown tuple.
            return (record.class, record.model) == (class, model)
                && matches!(
                    record.action,
                    MULTIPART_SEGMENT_ACTION | MULTIPART_KILL_ACTION
                );
        }
        (record.class, record.model, record.action) == (class, model, action)
    }
}

fn bind_dynamic_source_record(
    slots: &mut [Level1ResetSourceSlot],
    source_slot: u16,
    occupant: SourceOccupant,
    global_rng: u32,
) {
    occupant
        .source_spawn_kind()
        .unwrap_or_else(|error| panic!("source slot {source_slot}: {error}"));
    let Some((class, model, action)) = occupant.dynamic_shape() else {
        return;
    };
    let record = &mut slots[usize::from(source_slot)];
    record.active = true;
    record.class = class;
    record.model = model;
    record.action = action;
    record.phase = 0;
    record.entity_rng = source_slot.wrapping_add(global_rng as u16);
    record.control_flags = 8;
}

fn bind_castle_association(
    association_slot: u16,
    source_slots: &mut [Level1ResetSourceSlot],
    castle_associations: &mut Vec<CastleAssociationEffect>,
    next_effect_id: &mut u32,
    global_rng: u32,
    owner_entity_index: u16,
    position: Position,
) -> u16 {
    let association_id = *next_effect_id;
    let occupant = SourceOccupant::CastleAssociation(association_id);
    bind_dynamic_source_record(source_slots, association_slot, occupant, global_rng);
    *next_effect_id = next_effect_id.wrapping_add(1).max(1);
    castle_associations.push(CastleAssociationEffect {
        id: association_id,
        source_entity_index: association_slot,
        owner_entity_index,
        position,
        life: CASTLE_ASSOCIATION_LIFE,
        update_count: 0,
        collision_attempted: false,
        active: true,
    });
    association_slot
}

/// The bounded remc2 entity arena for the Level 1 slice.
///
/// Gameplay objects remain in typed vectors while the port is being recovered,
/// but every live object must own exactly one source slot in this arena.  Slot
/// zero is the original sentinel.  The free stack is stored in the same order
/// as remc2: `pop()` returns the lowest available slot.
#[derive(Clone, Debug, Eq, PartialEq)]
struct Level1SourcePool {
    occupants: Box<[Option<SourceOccupant>]>,
    disabled: Box<[bool]>,
    replaceable: Box<[bool]>,
    free_stack: Vec<u16>,
    replaceable_stack: Vec<u16>,
    raw_replaceable_cursor: i32,
    replaced_imported_slots: Vec<u16>,
    replaced_authored_slots: Vec<(u16, u16)>,
    fallback_allocation_count: u32,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct SourcePoolAllocationRollback {
    slot: u16,
    previous_occupant: Option<SourceOccupant>,
    previous_disabled: bool,
    previous_replaceable: bool,
    from_free_stack: bool,
    raw_replaceable_cursor: i32,
    replaced_imported_len: usize,
    replaced_authored_len: usize,
    fallback_allocation_count: u32,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum SourceAllocationKind {
    Ordinary,
    Replacement,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct SourceAllocation {
    slot: u16,
    kind: SourceAllocationKind,
}

impl Level1SourcePool {
    #[cfg(test)]
    fn from_free_stack(free_stack: &[u16]) -> Result<Self, String> {
        let mut occupants = vec![Some(SourceOccupant::ImportedLive); ENTITY_POOL_SIZE];
        occupants[0] = Some(SourceOccupant::Reserved);
        for &slot in free_stack {
            let index = usize::from(slot);
            if slot == 0 || index >= ENTITY_POOL_SIZE {
                return Err("Level 1 free entity-slot stack contains an invalid slot".to_owned());
            }
            if occupants[index].is_none() {
                return Err(format!(
                    "Level 1 free entity-slot stack contains duplicate slot {slot}"
                ));
            }
            occupants[index] = None;
        }
        Ok(Self {
            occupants: occupants.into_boxed_slice(),
            disabled: vec![false; ENTITY_POOL_SIZE].into_boxed_slice(),
            replaceable: vec![false; ENTITY_POOL_SIZE].into_boxed_slice(),
            free_stack: free_stack.to_vec(),
            replaceable_stack: Vec::new(),
            raw_replaceable_cursor: -1,
            replaced_imported_slots: Vec::new(),
            replaced_authored_slots: Vec::new(),
            fallback_allocation_count: 0,
        })
    }

    fn from_reset_slots(slots: &[Level1ResetSourceSlot]) -> Result<Self, String> {
        if slots.len() != ENTITY_POOL_SIZE {
            return Err(format!(
                "Level 1 reset source projection must contain exactly {ENTITY_POOL_SIZE} slots"
            ));
        }
        let mut occupants = Vec::with_capacity(ENTITY_POOL_SIZE);
        for (index, slot) in slots.iter().copied().enumerate() {
            if usize::from(slot.index) != index {
                return Err(format!(
                    "Level 1 reset source slot/index mismatch at {index}: {}",
                    slot.index
                ));
            }
            if index == 0 {
                occupants.push(Some(SourceOccupant::Reserved));
            } else if slot.active {
                occupants.push(Some(SourceOccupant::ImportedLive));
            } else {
                occupants.push(None);
            }
        }
        let free_stack = (1..slots.len())
            .rev()
            .filter(|index| !slots[*index].active)
            .map(|index| u16::try_from(index).expect("source pool index fits u16"))
            .collect();
        let replaceable_stack: Vec<u16> = (1..slots.len())
            .rev()
            .filter(|index| slots[*index].active && slots[*index].replaceable())
            .map(|index| u16::try_from(index).expect("source pool index fits u16"))
            .collect();
        let raw_replaceable_cursor =
            i32::try_from(replaceable_stack.len()).expect("replaceable stack length fits i32") - 1;
        Ok(Self {
            occupants: occupants.into_boxed_slice(),
            disabled: vec![false; ENTITY_POOL_SIZE].into_boxed_slice(),
            replaceable: slots
                .iter()
                .map(|slot| slot.replaceable())
                .collect::<Vec<_>>()
                .into_boxed_slice(),
            free_stack,
            replaceable_stack,
            raw_replaceable_cursor,
            replaced_imported_slots: Vec::new(),
            replaced_authored_slots: Vec::new(),
            fallback_allocation_count: 0,
        })
    }

    fn allocate_with_kind(&mut self, occupant: SourceOccupant) -> Option<SourceAllocation> {
        let (slot, from_free_stack) = if let Some(slot) = self.free_stack.pop() {
            (slot, true)
        } else {
            if self.raw_replaceable_cursor < 0 {
                return None;
            }
            let slot = self.replaceable_stack.pop()?;
            self.raw_replaceable_cursor = self.raw_replaceable_cursor.wrapping_sub(1);
            (slot, false)
        };
        if !from_free_stack {
            self.fallback_allocation_count = self.fallback_allocation_count.wrapping_add(1);
        }
        let index = usize::from(slot);
        let was_replaceable = self.replaceable[index];
        let entry = self
            .occupants
            .get_mut(index)
            .expect("validated source slot");
        assert!(
            entry.is_none()
                || was_replaceable
                || matches!(
                    *entry,
                    Some(
                        SourceOccupant::ImportedLive
                            | SourceOccupant::Ambient(_)
                            | SourceOccupant::Authored(_)
                    )
                ),
            "allocatable source slot {slot} has a live typed occupant"
        );
        if *entry == Some(SourceOccupant::ImportedLive) {
            self.replaced_imported_slots.push(slot);
        } else if let Some(SourceOccupant::Authored(authored_index)) = *entry {
            self.replaced_authored_slots.push((slot, authored_index));
        }
        *entry = Some(occupant);
        self.disabled[index] = false;
        self.replaceable[index] = false;
        debug_assert!(
            from_free_stack
                || self.raw_replaceable_cursor
                    == i32::try_from(self.replaceable_stack.len())
                        .expect("replaceable stack length fits i32")
                        - 1
        );
        Some(SourceAllocation {
            slot,
            kind: if from_free_stack {
                SourceAllocationKind::Ordinary
            } else {
                SourceAllocationKind::Replacement
            },
        })
    }

    #[cfg(test)]
    fn allocate(&mut self, occupant: SourceOccupant) -> Option<u16> {
        self.allocate_with_kind(occupant)
            .map(|allocation| allocation.slot)
    }

    fn next_allocation_rollback(&self) -> Option<SourcePoolAllocationRollback> {
        let (slot, from_free_stack) = self
            .free_stack
            .last()
            .copied()
            .map(|slot| (slot, true))
            .or_else(|| {
                self.replaceable_stack
                    .last()
                    .copied()
                    .map(|slot| (slot, false))
            })?;
        let index = usize::from(slot);
        Some(SourcePoolAllocationRollback {
            slot,
            previous_occupant: self.occupants[index],
            previous_disabled: self.disabled[index],
            previous_replaceable: self.replaceable[index],
            from_free_stack,
            raw_replaceable_cursor: self.raw_replaceable_cursor,
            replaced_imported_len: self.replaced_imported_slots.len(),
            replaced_authored_len: self.replaced_authored_slots.len(),
            fallback_allocation_count: self.fallback_allocation_count,
        })
    }

    fn rollback_allocation(&mut self, rollback: SourcePoolAllocationRollback) {
        let index = usize::from(rollback.slot);
        self.occupants[index] = rollback.previous_occupant;
        self.disabled[index] = rollback.previous_disabled;
        self.replaceable[index] = rollback.previous_replaceable;
        self.replaced_imported_slots
            .truncate(rollback.replaced_imported_len);
        self.replaced_authored_slots
            .truncate(rollback.replaced_authored_len);
        self.fallback_allocation_count = rollback.fallback_allocation_count;
        self.raw_replaceable_cursor = rollback.raw_replaceable_cursor;
        if rollback.from_free_stack {
            self.free_stack.push(rollback.slot);
        } else {
            self.replaceable_stack.push(rollback.slot);
        }
    }

    fn has_ordinary_free_slot(&self) -> bool {
        !self.free_stack.is_empty()
    }

    #[cfg(test)]
    fn release(&mut self, slot: u16) -> bool {
        if slot == 0 {
            return false;
        }
        let Some(entry) = self.occupants.get_mut(usize::from(slot)) else {
            return false;
        };
        if entry.is_none() {
            return false;
        }
        *entry = None;
        self.disabled[usize::from(slot)] = false;
        self.replaceable[usize::from(slot)] = false;
        self.replaceable_stack
            .retain(|candidate| *candidate != slot);
        self.free_stack.push(slot);
        true
    }

    #[cfg(test)]
    fn release_occupant(&mut self, occupant: SourceOccupant) -> bool {
        let Some(slot) = self
            .occupants
            .iter()
            .position(|candidate| *candidate == Some(occupant))
            .and_then(|index| u16::try_from(index).ok())
        else {
            return false;
        };
        self.release(slot)
    }

    fn disable_slot(&mut self, slot: u16) -> bool {
        if slot == 0 {
            return false;
        }
        let index = usize::from(slot);
        if self.occupants.get(index).is_none_or(Option::is_none) {
            return false;
        }
        self.disabled[index] = true;
        true
    }

    fn disable_occupant(&mut self, occupant: SourceOccupant) -> bool {
        let Some(slot) = self
            .occupants
            .iter()
            .position(|candidate| *candidate == Some(occupant))
            .and_then(|index| u16::try_from(index).ok())
        else {
            return false;
        };
        self.disable_slot(slot)
    }

    fn replace_occupant(&mut self, slot: u16, occupant: SourceOccupant) {
        let entry = self
            .occupants
            .get_mut(usize::from(slot))
            .expect("validated source slot");
        assert!(entry.is_some(), "cannot replace an unallocated source slot");
        *entry = Some(occupant);
    }

    fn mark_replaceable(&mut self, slot: u16) {
        let index = usize::from(slot);
        assert!(
            self.occupants.get(index).is_some_and(Option::is_some),
            "cannot mark an unallocated source slot replaceable"
        );
        self.replaceable[index] = true;
    }

    /// `sub_57F20` is called directly for an absorbed mana sphere, so that
    /// source slot becomes allocatable immediately rather than at the next
    /// `UpdateEntities_57730` sweep.
    fn reclaim_slot_immediately(&mut self, slot: u16) -> bool {
        if slot == 0 {
            return false;
        }
        let Some(entry) = self.occupants.get_mut(usize::from(slot)) else {
            return false;
        };
        if entry.is_none() {
            return false;
        }
        *entry = None;
        self.disabled[usize::from(slot)] = false;
        self.replaceable[usize::from(slot)] = false;
        self.replaceable_stack
            .retain(|candidate| *candidate != slot);
        self.free_stack.push(slot);
        true
    }

    /// `UpdateEntities_57730` reclaims disabled slots in ascending order and
    /// appends them to the existing allocation stack.
    fn reclaim_disabled_ascending(&mut self) -> Vec<u16> {
        let mut reclaimed = Vec::new();
        for index in 1..self.occupants.len() {
            if !self.disabled[index] {
                continue;
            }
            self.occupants[index] = None;
            self.disabled[index] = false;
            self.replaceable[index] = false;
            let slot = u16::try_from(index).expect("source pool index fits u16");
            self.replaceable_stack
                .retain(|candidate| *candidate != slot);
            self.free_stack.push(slot);
            reclaimed.push(slot);
        }
        reclaimed
    }

    /// `sub_49F90` rebuilds the allocation stack by scanning 999 down to 1
    /// immediately before authored group activation.
    fn rebuild_free_stack(&mut self) {
        let _ = self.reclaim_disabled_ascending();
        self.free_stack.clear();
        self.free_stack.extend(
            (1..self.occupants.len())
                .rev()
                .filter(|index| self.occupants[*index].is_none())
                .map(|index| u16::try_from(index).expect("source pool index fits u16")),
        );
        self.replaceable_stack.clear();
        self.replaceable_stack.extend(
            (1..self.occupants.len())
                .rev()
                .filter(|index| {
                    self.replaceable[*index]
                        && self.occupants[*index].is_some()
                        && self.occupants[*index] != Some(SourceOccupant::Reserved)
                })
                .map(|index| u16::try_from(index).expect("source pool index fits u16")),
        );
        self.raw_replaceable_cursor = i32::try_from(self.replaceable_stack.len())
            .expect("replaceable stack length fits i32")
            - 1;
    }

    /// The dying-contact tail literally decrements `dword_0x11e6` after the
    /// marker constructor, even after that constructor already consumed the
    /// last replacement row or failed. When a replacement remains, the
    /// decrement discards that row from subsequent allocation.
    fn decrement_replaceable_cursor_after_player_contact(&mut self) {
        if self.raw_replaceable_cursor >= 0 {
            let _ = self.replaceable_stack.pop();
        }
        self.raw_replaceable_cursor = self.raw_replaceable_cursor.wrapping_sub(1);
    }

    fn occupant(&self, slot: u16) -> Option<SourceOccupant> {
        self.occupants.get(usize::from(slot)).copied().flatten()
    }

    fn take_replaced_imported_slots(&mut self) -> Vec<u16> {
        std::mem::take(&mut self.replaced_imported_slots)
    }

    fn take_replaced_authored_slots(&mut self) -> Vec<(u16, u16)> {
        std::mem::take(&mut self.replaced_authored_slots)
    }
}

