        assert_eq!(higher.source_pool.occupant(600), None);
        assert!(higher.dynamic_residents[600].is_none());

        let mut lower = template.session(10_000, 1_000);
        lower.source_pool = Level1SourcePool::from_free_stack(&[100]).unwrap();
