    fn imported_firefly_views(
        mission: &mut Level1MissionState,
        seeker_position: Position,
    ) -> Vec<Level1SourceEntityView> {
        let mut extra_views = Vec::new();
        for slot in [140_u16, 141_u16] {
            mission.source_pool.occupants[usize::from(slot)] = Some(SourceOccupant::ImportedLive);
            mission.source_pool.disabled[usize::from(slot)] = false;
            let record = Level1ResetSourceSlot {
                index: slot,
                active: true,
                class: 3,
                model: 0,
                action: 0,
                phase: u8::try_from(slot).expect("focused Firefly source slot fits u8"),
                entity_rng: slot,
                control_flags: 8,
            };
            mission.source_slots[usize::from(slot)] = record;
            let mut view = Level1SourceEntityView::imported_record(record);
            view.source_id = slot;
            view.position = Position {
                x: seeker_position.x,
                y: seeker_position.y.wrapping_sub(512),
                z: seeker_position.z,
            };
            view.life = 100;
            view.max_life = 100;
            extra_views.push(view);
        }
        extra_views.reverse();
        extra_views
    }

    fn assert_firefly_rebuilt_candidate_order(
        mission: &mut Level1MissionState,
        actor_index: usize,
        source_slot: u16,
        player: FlightState,
    ) {
        let seeker_position = mission.actors[actor_index].position;
        let mut extra_views = imported_firefly_views(mission, seeker_position);
        {
            let actor = &mut mission.actors[actor_index];
            actor.action = FIREFLY_ROAM_ACTION;
            actor.target_entity_index = 0;
            actor.linked_entity_index = 0;
            actor.phase = 0;
            actor.actual_speed = 0;
            actor.yaw = 0;
            actor.desired_heading = 0;
        }
        let distant_player = FlightState {
            position: Position {
                x: seeker_position.x,
                y: seeker_position.y.wrapping_add(FIREFLY_RANGE + 1),
                z: seeker_position.z,
            },
            ..player
        };
        mission.dispatch_source_slot_with_views_and_look(
            &FlatWorld,
            &distant_player,
            &extra_views,
            source_slot,
            false,
            false,
            None,
            0,
            0,
        );
        assert!(
            !matches!(mission.actors[actor_index].target_entity_index, 140 | 141),
            "same-turn class-three insertion is absent from the frozen rebuilt list"
        );

        mission.begin_source_turn_at(distant_player.position);
        {
            let actor = &mut mission.actors[actor_index];
            actor.action = FIREFLY_ROAM_ACTION;
            actor.target_entity_index = 0;
            actor.linked_entity_index = 0;
            actor.phase = 0;
            actor.actual_speed = 0;
            actor.yaw = 0;
            actor.desired_heading = 0;
        }
        mission.dispatch_source_slot_with_views_and_look(
            &FlatWorld,
            &distant_player,
            &extra_views,
            source_slot,
            false,
            false,
            None,
            0,
            0,
        );
        assert_eq!(
            mission.actors[actor_index].target_entity_index, 140,
            "equal distance retains ascending rebuilt-list order, not supplied view order"
        );

        let slot_141 = extra_views
            .iter_mut()
            .find(|view| view.source_entity_index == 141)
            .unwrap();
        slot_141.position.y = seeker_position.y.wrapping_sub(256);
        let slot_141 = *slot_141;
        mission.refresh_source_turn_entity(&distant_player, 141, Some(slot_141));
        {
            let actor = &mut mission.actors[actor_index];
            actor.action = FIREFLY_ROAM_ACTION;
            actor.target_entity_index = 0;
            actor.phase = 0;
        }
        mission.dispatch_source_slot_with_views_and_look(
            &FlatWorld,
            &distant_player,
            &extra_views,
            source_slot,
            false,
            false,
            None,
            0,
            0,
        );
        assert_eq!(
            mission.actors[actor_index].target_entity_index, 141,
            "live candidate relocation may replace the first source row on strict improvement"
        );
    }

    #[test]
    fn firefly_stage_arrival_hands_off_to_roam_before_same_turn_dispatch() {
        let template = Level1MissionTemplate::decode(&authored_bytes(), &FlatWorld).unwrap();
        let mut mission = template.session(10_000, 1_000);
        mission.activate_group(6);
        let actor_index = mission
            .actors
            .iter()
            .position(|actor| actor.kind == Level1ActorKind::Firefly)
            .unwrap();
        let source_slot = mission.actors[actor_index].source_entity_index;
        let player = FlightState {
            entity_index: 152,
            position: Position {
                x: FIREFLY_STAGE_TARGET.x.wrapping_add(1_000),
                y: FIREFLY_STAGE_TARGET.y,
                z: FIREFLY_STAGE_TARGET.z,
            },
            ..FlightState::default()
        };
        {
            let actor = &mut mission.actors[actor_index];
            actor.position = FIREFLY_STAGE_TARGET;
            actor.phase = FIREFLY_DECISION_CADENCE;
            actor.yaw =
                i16::try_from(heading_for_positions(actor.position, player.position)).unwrap();
            actor.desired_heading = actor.yaw;
            actor.action = FIREFLY_STAGE_ACTION;
            actor.stage_var_1 = 8;
            actor.stage_var_2 = 1;
        }

        mission.begin_source_turn();

        let actor = mission.actors[actor_index];
        assert_eq!(actor.action, FIREFLY_ROAM_ACTION);
        assert_eq!(actor.stage_var_1, 0);
        assert_eq!(actor.stage_var_2, 0);
        assert_eq!(actor.linked_entity_index, 0);

        mission.dispatch_source_slot(&FlatWorld, &player, source_slot, false, false, None);

        assert_eq!(
            mission.actors[actor_index].action, FIREFLY_ATTACK_ACTION,
            "the newly selected roam action must acquire the visible player on the same source turn"
        );
        assert_eq!(mission.actors[actor_index].attack_substate, 0);
        assert_eq!(
            mission.source_slots[usize::from(source_slot)].action,
            FIREFLY_ATTACK_ACTION
        );
        assert_firefly_rebuilt_candidate_order(&mut mission, actor_index, source_slot, player);
    }

    fn assert_firefly_linked_hit_propagates(template: &Level1MissionTemplate, player: FlightState) {
        let mut mission = template.session(10_000, 1_000);
        mission.activate_group(6);
        let mut firefly_indices = mission
            .actors
            .iter()
            .enumerate()
            .filter(|(_, actor)| actor.kind == Level1ActorKind::Firefly && actor.active)
            .map(|(index, _)| index)
            .collect::<Vec<_>>();
        firefly_indices.sort_unstable_by_key(|index| mission.actors[*index].source_entity_index);
        let peer_index = firefly_indices[0];
        let struck_index = *firefly_indices.last().unwrap();
        let peer_slot = mission.actors[peer_index].source_entity_index;
        {
            let peer = &mut mission.actors[peer_index];
            peer.action = FIREFLY_ROAM_ACTION;
            peer.target_entity_index = 0;
            peer.linked_entity_index = 0;
            peer.attack_substate = 0;
            peer.stage_var_1 = 0;
            peer.stage_var_2 = 0;
        }
        {
            let struck = &mut mission.actors[struck_index];
            struck.position = Position {
                x: 40_000,
                y: 40_000,
                z: 0,
            };
            struck.action = FIREFLY_LINKED_ACTION;
            struck.target_entity_index = 0;
            struck.linked_entity_index = peer_slot;
            struck.attack_substate = 0;
            struck.stage_var_1 = 0;
            struck.stage_var_2 = 0;
            struck.pending_damage = 50;
            struck.pending_attacker = 35;
        }

        mission.step(&FlatWorld, &player);

        let peer = mission.actors[peer_index];
        let struck = mission.actors[struck_index];
        assert_eq!(
            (
                peer.target_entity_index,
                peer.linked_entity_index,
                peer.action
            ),
            (35, 0, FIREFLY_ATTACK_ACTION),
            "action-155 alerts the valid linked peer before rewriting the struck Firefly"
        );
        assert_eq!(struck.life, FIREFLY_LIFE - 50);
        assert_eq!(
            (
                struck.target_entity_index,
                struck.linked_entity_index,
                struck.action,
                struck.attack_substate,
            ),
            (35, 0, FIREFLY_ATTACK_ACTION, 0)
        );
    }

    fn configure_firefly_stage_hit(actor: &mut Level1Actor, attacker: u16) {
        actor.position = Position {
            x: 40_000,
            y: 40_000,
            z: 0,
        };
        actor.action = FIREFLY_STAGE_ACTION;
        actor.target_entity_index = 0;
        actor.stage_var_1 = 8;
        actor.stage_var_2 = 1;
        actor.pending_damage = 50;
        actor.pending_attacker = attacker;
    }

    fn assert_firefly_stage_hit_filters_same_family_and_player(
        template: &Level1MissionTemplate,
        player: FlightState,
    ) {
        let mut mission = template.session(10_000, 1_000);
        mission.activate_group(6);
        let mut firefly_indices = mission
            .actors
            .iter()
            .enumerate()
            .filter(|(_, actor)| actor.kind == Level1ActorKind::Firefly && actor.active)
            .map(|(index, _)| index)
            .collect::<Vec<_>>();
        firefly_indices.sort_unstable_by_key(|index| mission.actors[*index].source_entity_index);
        let same_family_index = firefly_indices[0];
        let struck_index = *firefly_indices.last().unwrap();
        let same_family_slot = mission.actors[same_family_index].source_entity_index;
        configure_firefly_stage_hit(&mut mission.actors[struck_index], same_family_slot);

        mission.step(&FlatWorld, &player);

        let struck = mission.actors[struck_index];
        assert_eq!(struck.life, FIREFLY_LIFE - 50);
        assert_eq!(
            (
                struck.target_entity_index,
                struck.action,
                struck.stage_var_1,
                struck.stage_var_2,
            ),
            (0, FIREFLY_STAGE_ACTION, 8, 1),
            "same-class/model damage remains in stage behavior"
        );

        configure_firefly_stage_hit(&mut mission.actors[struck_index], player.entity_index);
        mission.step(&FlatWorld, &player);
        let struck = mission.actors[struck_index];
        assert_eq!(struck.life, FIREFLY_LIFE - 100);
        assert_eq!(
            (
                struck.target_entity_index,
                struck.action,
                struck.stage_var_2,
                struck.attack_substate,
            ),
            (player.entity_index, FIREFLY_ATTACK_ACTION, 10, 0),
            "a player is a different class/model and enters Firefly attack"
        );
    }

    fn assert_firefly_stage_hit_accepts_non_family(
        template: &Level1MissionTemplate,
        player: FlightState,
    ) {
        let mut non_family = template.session(10_000, 1_000);
        non_family.activate_group(3);
        non_family.activate_group(6);
        let attacker = non_family
            .actors
            .iter()
            .find(|actor| actor.kind == Level1ActorKind::Archer && actor.active)
            .map(|actor| actor.source_entity_index)
            .expect("group 3 activates a non-family Archer");
        let struck_index = non_family
            .actors
            .iter()
            .enumerate()
            .filter(|(_, actor)| actor.kind == Level1ActorKind::Firefly && actor.active)
            .max_by_key(|(_, actor)| actor.source_entity_index)
            .map(|(index, _)| index)
            .unwrap();
        configure_firefly_stage_hit(&mut non_family.actors[struck_index], attacker);
        non_family.step(&FlatWorld, &player);
        let struck = non_family.actors[struck_index];
        assert_eq!(
            (
                struck.target_entity_index,
                struck.action,
                struck.attack_substate,
            ),
            (attacker, FIREFLY_ATTACK_ACTION, 0),
            "a different class/model source enters Firefly attack"
        );
    }

    #[test]
    fn hostile_hit_enters_firefly_attack_and_death_waits_for_phase_gate() {
        let template = Level1MissionTemplate::decode(&authored_bytes(), &FlatWorld).unwrap();
        let mut mission = template.session(10_000, 1_000);
        mission.activate_group(6);
        let actor_index = mission
            .actors
            .iter()
            .position(|actor| actor.kind == Level1ActorKind::Firefly)
            .unwrap();
        let player = FlightState {
            entity_index: 152,
            position: Position {
                x: 60_000,
                y: 47_000,
                z: 1_000,
            },
            ..FlightState::default()
        };
        let authored_index = mission.actors[actor_index].authored_index;
        mission.actors[actor_index].action = FIREFLY_ROAM_ACTION;
        mission.actors[actor_index].pending_damage = 250;
        mission.actors[actor_index].pending_attacker = 33;
        mission.step(&FlatWorld, &player);
        assert_eq!(mission.actors[actor_index].life, 350);
        assert_eq!(mission.actors[actor_index].action, FIREFLY_ATTACK_ACTION);
        assert_eq!(mission.actors[actor_index].target_entity_index, 33);
        assert_eq!(mission.actors[actor_index].attack_substate, 0);
        assert!(mission.events().iter().any(|event| matches!(
            event,
            Level1MissionEvent::ActorDamaged {
                authored_index: event_authored_index,
                attacker_entity_index: 33,
                damage: 250,
                life: 350,
            } if *event_authored_index == authored_index
        )));

        mission.actors[actor_index].action = FIREFLY_ATTACK_ACTION;
        mission.actors[actor_index].pending_damage = 100;
        mission.actors[actor_index].pending_attacker = 34;
        mission.step(&FlatWorld, &player);
        assert_eq!(mission.actors[actor_index].life, 250);
        assert_eq!(mission.actors[actor_index].target_entity_index, 34);
        assert_eq!(
            mission.actors[actor_index].attack_substate, 7,
            "an already-attacking Firefly resumes at HitFirebug's charge substate"
        );
        assert!(mission.events().iter().any(|event| matches!(
            event,
            Level1MissionEvent::ActorDamaged {
                authored_index: event_authored_index,
                attacker_entity_index: 34,
                damage: 100,
                life: 250,
            } if *event_authored_index == authored_index
        )));

        mission.actors[actor_index].pending_damage = 500;
        mission.actors[actor_index].pending_attacker = player.entity_index;
        mission.step(&FlatWorld, &player);
        assert!(mission.actors[actor_index].life < 0);
        assert_eq!(mission.actors[actor_index].action, FIREFLY_PRE_KILL_ACTION);
        mission.step(&FlatWorld, &player);
        assert_eq!(mission.actors[actor_index].action, FIREFLY_KILL_ACTION);
        for _ in 0..8 {
            if !mission.actors[actor_index].active {
                break;
            }
            mission.step(&FlatWorld, &player);
        }
        assert!(!mission.actors[actor_index].active);

        assert_firefly_linked_hit_propagates(&template, player);
        assert_firefly_stage_hit_filters_same_family_and_player(&template, player);
        assert_firefly_stage_hit_accepts_non_family(&template, player);
    }

    #[test]
    fn firefly_ranged_and_charge_attacks_use_distinct_source_constants() {
        let template = Level1MissionTemplate::decode(&authored_bytes(), &FlatWorld).unwrap();
        let mut actor = template
            .actors()
            .iter()
            .find(|actor| actor.kind == Level1ActorKind::Firefly)
            .copied()
            .unwrap();
        actor.active = true;
        actor.source_entity_index = 10;
        actor.position = Position {
            x: 20_000,
            y: 20_000,
            z: 1_000,
        };
        actor.target_entity_index = 152;
        actor.action = FIREFLY_ATTACK_ACTION;
        actor.attack_substate = 5;
        actor.phase = FIREFLY_DECISION_CADENCE;
        actor.actual_speed = 0;
        let player = FlightState {
            entity_index: 152,
            position: Position {
                x: 20_000,
                y: 18_000,
                z: 1_000,
            },
            ..FlightState::default()
        };
        let views = [actor];
        let (projectile, sound, damage) =
            step_firefly_attack(&mut actor, &FlatWorld, &player, &views, 77);
        let projectile = projectile.expect("state 5 must fire in range on cadence");
        assert_eq!(sound, None);
        assert_eq!(damage, 0);
        assert_eq!(projectile.id, 77);
        assert_eq!(projectile.speed, FIREFLY_FIREBALL_SPEED);
        assert_eq!(projectile.life_ticks, FIREFLY_FIREBALL_LIFETIME_TICKS);
        assert_eq!(projectile.payload, FIREFLY_FIREBALL_PAYLOAD);
        assert_eq!(projectile.position.z, actor.position.z + 51);
        assert_eq!(projectile.target_entity_index, player.entity_index);
        assert_eq!(
            projectile.pitch,
            pitch_for_delta(
                i32::try_from(legacy_sqrt(squared_wrapping_xy_distance(
                    actor.position,
                    player.position,
                )))
                .unwrap(),
                i32::from(player.position.z.wrapping_sub(actor.position.z)),
            ),
            "source calculates aim from the Firefly origin before raising the projectile by 51"
        );

        actor.position = player.position;
        actor.actual_speed = 0;
        actor.attack_substate = 7;
        actor.state_value = 0;
        let rng_before = actor.entity_rng;
        let (_, sound, damage) = step_firefly_attack(&mut actor, &FlatWorld, &player, &views, 78);
        assert_eq!(sound, Some(43 + (next_rng16(rng_before) & 1)));
        assert_eq!(damage, FIREFLY_CONTACT_DAMAGE);
        assert_eq!(actor.attack_substate, 9);
        let (_, _, repeated_damage) =
            step_firefly_attack(&mut actor, &FlatWorld, &player, &views, 79);
        assert_eq!(repeated_damage, 0);
    }

